var r=[{title:`Akuta symtom`,text:`Sluta träna omedelbart om du har bröstsmärta eller tryck över bröstet, svimmar, blir mycket andfådd utan tydlig orsak, känner plötslig svaghet på ena sidan, har en svår ny huvudvärk med neurologiska förändringar eller om en allvarlig reaktion utvecklas snabbt. Obehag i bröstet med svettning, illamående, yrsel eller smärta som strålar mot armen eller käken kräver ambulans.`},{title:`Andra allvarliga varningstecken`,text:`Träna inte vidare vid plötslig svår led- eller ryggsmärta, tydlig svullnad efter en skada, oförmåga att belasta, svaghet som förvärras eller ny domning. Ryggsmärta tillsammans med förlust av blås- eller tarmkontroll eller domning kring ljumsken kräver akut bedömning direkt.`},{title:`Vad du ska göra`,text:`Sluta, gör området säkert och ta hjälp. Ring ditt lokala nödnummer vid akuta symtom och kör inte själv om du kan vara allvarligt sjuk eller skadad. Om du är träningspartner, försök inte lista ut orsaken och uppmuntra inte personen att avsluta setet. TrainUp kan inte bedöma en nödsituation, diagnostisera sjukdom eller ersätta en kvalificerad yrkesperson.`},{title:`Förebyggande har gränser`,text:`Uppvärmning, rimliga vikter och gradvis progression kan minska onödig belastning, men de kan inte utesluta alla medicinska problem. Om du har känd hjärtsjukdom eller stora riskfaktorer kan du behöva personliga råd från din läkare innan du börjar med intensiv träning.`}];var t=[{label:`NHS: bröstsmärta och akuta symtom`,url:`https://www.nhs.uk/symptoms/chest-pain/`},{label:`NHS: ryggsmärta och akuta varningstecken`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`NHS: ledsmärta`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var n={sections:r,sources:t};export{n as default,r as sections,t as sources};